export type ContractFamily = keyof typeof CONTRACTS
type ContractEnv = keyof (typeof CONTRACTS)[ContractFamily]
type ContractVersion = string

/** Maps each contract family to a flat { [version]: address } lookup for a given env. */
type VersionMap = Record<ContractVersion, string>

export function getContractAddress(family: ContractFamily): string {
  const env = ENV.contractEnv as ContractEnv
  const version = ENV.contractVersion
  const versions = CONTRACTS[family][env] as VersionMap
  const addr = versions[version]
  if (!addr || typeof addr !== "string") {
    throw new Error(
      `Contract address not configured for ${family} on ${env}/${version}. Run contracts/deploy.sh to update registry.`,
    )
  }
  return addr
}
